import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Teacher Dashboard -> Overview Analytics (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/overview-analytics.md","filePath":"modules/teacher-dashboard/overview-analytics.md"}'),d={name:"modules/teacher-dashboard/overview-analytics.md"};function s(i,e,n,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="teacher-dashboard-overview-analytics-deep" tabindex="-1">Teacher Dashboard -&gt; Overview Analytics (deep) <a class="header-anchor" href="#teacher-dashboard-overview-analytics-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Overview Analytics (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>overview-analytics</code><br><strong>Route:</strong> <code>/teacher-dashboard/overview</code></p><p>This screen is the instructor’s analytics dashboard. It shows platform-facing instructor stats such as cumulative students, active bookings, money earned, attendance/cancellation rates, average lessons per student, the most recently trained student, a calendar summary, and a map.</p><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/InstructorAnalyticsDashboard.tsx</code></td><td>Main overview screen</td><td>Defines inline <code>GET_INSTRUCTOR_ANALYTICS</code>; uses <code>useAuth</code> for <code>user.id</code>; renders stats cards, last student, overview availability, and map.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/StatsCard.tsx</code></td><td>Reusable metric card</td><td>Pure UI for top stat blocks.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/LastTrainedStudent.tsx</code></td><td>Recent-student summary card</td><td>Displays last booking student info and lesson metadata.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/AvailabilityCalendar.tsx</code></td><td>Overview calendar widget</td><td>Uses teacher availability GraphQL to show availability distribution inside overview.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/InstructorMap.tsx</code></td><td>Map display</td><td>Uses instructor address from analytics payload.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/InstructorAnalytics/ProgressMetric.tsx</code></td><td>Percentage/stat cards</td><td>Used for attendance, cancellation, and average-lessons metrics.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/common/LoadingSpinner.tsx</code></td><td>Loading state</td><td>Used while analytics query is in flight.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-instructor-analytics" tabindex="-1"><code>GET_INSTRUCTOR_ANALYTICS</code> <a class="header-anchor" href="#get-instructor-analytics" aria-label="Permalink to &quot;`GET_INSTRUCTOR_ANALYTICS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/components/InstructorComponent/InstructorAnalytics/InstructorAnalyticsDashboard.tsx</code></li><li>Query field: <code>getInstructorAnalytics(instructorId: ID!)</code></li><li>Variables: <ul><li><code>instructorId</code> from <code>useAuth().user.id</code></li></ul></li><li>Requested fields: <ul><li><code>totalStudents</code></li><li><code>activeBookings</code></li><li><code>totalEarnings</code></li><li><code>averageLessonsPerStudent</code></li><li><code>cancellationRate</code></li><li><code>attendanceRate</code></li><li><code>lastBooking { ... }</code></li><li><code>instructor { firstName, lastName, email, address }</code></li></ul></li></ul><h3 id="availability-summary-dependency" tabindex="-1">Availability summary dependency <a class="header-anchor" href="#availability-summary-dependency" aria-label="Permalink to &quot;Availability summary dependency&quot;">​</a></h3><ul><li>File: <code>Frontend/src/components/InstructorComponent/InstructorAnalytics/AvailabilityCalendar.tsx</code></li><li>Uses: <ul><li><code>GET_TEACHER_AVAILABILITY</code></li><li><code>ADD_AVAILABILITY_SLOT</code></li><li><code>DELETE_AVAILABILITY_SLOT</code></li></ul></li><li>This file is part of the overview surface but reuses the main availability module backend.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/instructorPublic.typeDefs.js</code></li><li>Relevant query field: <ul><li><code>getInstructorAnalytics(instructorId: ID!): InstructorAnalytics!</code></li></ul></li><li>Relevant types: <ul><li><code>InstructorAnalytics</code></li><li><code>StudentBookingNew</code></li><li><code>SlotNew</code></li><li><code>UserNew</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/instructorPublic.resolver.js</code></li><li>Relevant resolver: <ul><li><code>Query.getInstructorAnalytics</code><ul><li>Builds instructor-facing dashboard metrics</li><li>Uses <code>studentBookingModel</code> as the main source for bookings/slots</li><li>Uses <code>User</code>/instructor data for instructor metadata</li><li>Returns last booking/student summary data used by the UI</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Source of booking/slot metrics</td></tr><tr><td><code>server/src/models/User.js</code></td><td>Source of instructor profile/address data</td></tr><tr><td><code>server/src/graphql/typeDefs/availability.js</code></td><td>Supports the overview availability sub-widget</td></tr><tr><td><code>server/src/graphql/resolvers/availability.resolver.js</code></td><td>Supplies calendar slot summaries used by overview calendar</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens <code>/teacher-dashboard/overview</code>.</li><li><code>InstructorAnalyticsDashboard.tsx</code> reads the current instructor id from <code>AuthContext</code>.</li><li>It calls <code>getInstructorAnalytics(instructorId)</code>.</li><li>Backend aggregates booking and student data into one <code>InstructorAnalytics</code> payload.</li><li>Frontend renders: <ul><li>top stat cards</li><li>last trained student</li><li>availability summary widget</li><li>instructor map</li><li>attendance/cancellation progress metrics</li></ul></li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li><code>InstructorAnalyticsDashboard.tsx</code> defines its GraphQL query inline instead of importing it from a shared query file.</li><li>The card labeled “Licensed Students” currently derives its value with a frontend assumption (<code>studentsCount * 0.8</code> style logic), not a dedicated backend field.</li><li><code>Frontend/src/pages/private/teacher-dashboard/teacher0verview.tsx</code> appears legacy/unwired; the live route points to <code>InstructorAnalyticsDashboard</code>.</li></ul>',21)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
